const vector = $json.data[0].embedding;
const literal = '[' + vector.join(',') + ']';
const sql = "SELECT p.numero_documento, p.primer_nombre, p.segundo_nombre, p.apellidos, p.fecha_nacimiento, 1 - (pe.embedding <=> '" + literal + "'::vector) AS similitud FROM persona_embeddings pe JOIN personas p ON p.numero_documento = pe.numero_documento ORDER BY pe.embedding <=> '" + literal + "'::vector LIMIT 5";
return [{ json: { sql } }];

const original = $('Chat Trigger').first().json.chatInput || '';
const pregunta = original.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const rango = pregunta.match(/(?:mas de|mayor(?:es)? de|superior a|al menos|menos de|menor(?:es)? de)\s+(\d{1,3})/);
const exacta = pregunta.match(/(?:tienen|de|con)\s+(\d{1,3})\s+anos/);
let ageMode = '';
let ageLimit = 0;
if (rango) {
  ageMode = /^(?:menos de|menor)/.test(rango[0]) ? 'lt' : /^al menos/.test(rango[0]) ? 'gte' : 'gt';
  ageLimit = Number(rango[1]);
} else if (exacta) {
  ageMode = 'eq';
  ageLimit = Number(exacta[1]);
}
const camposNoDisponibles = [];
if (/\b(direccion|ciudad|municipio|barrio|donde|vive|viven)\b/.test(pregunta)) camposNoDisponibles.push('dirección y ciudad');
if (/\b(cargo|area|puesto|profesion|trabaja|trabajan)\b/.test(pregunta)) camposNoDisponibles.push('cargo y área de trabajo');
const documento = pregunta.match(/(?:documento|cedula|identificacion)\D{0,15}(\d{5,10})/) || (!rango && pregunta.match(/\b\d{6,10}\b/));
const comunes = new Set('a al anos apellidos barrio cargo celular ciudad como con cual cuales de del documento donde edad el electronico empleado empleados empleada empleados en es esta estan existe fecha genero hay identificacion informacion la las los mas mayor mayores menor menores municipio nombre nacimiento nacio no numero o por persona personas profesion puesto que quien quienes registrado registrada registrados registradas registro se sexo son telefono tienen trabaja trabajan un una y vive viven correo email direccion area promedio total cuantos cuantas'.split(' '));
const objetivo = camposNoDisponibles.length ? '' : documento ? documento[1] : pregunta.replace(/[^a-z0-9]+/g, ' ').trim().split(/\s+/).filter((word) => word && !comunes.has(word) && !/^\d+$/.test(word)).join(' ');
return [{ json: { pregunta: original, objetivo, ageMode, ageLimit, camposNoDisponibles } }];

const consulta = $json;
const pregunta = consulta.pregunta.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const conteo = /\b(?:cuantos|cuantas)\b/.test(pregunta) && /\b(?:personas|empleados|hombres|mujeres|masculino|femenino)\b/.test(pregunta);
const ubicacion = /\b(direccion|direcciones|ciudad|ciudades|municipio|municipios|barrio|barrios|donde|vive|viven|reside|residen)\b|\b(?:son|viven|residen) (?:de|en) (?!genero|sexo|edad|documento|tipo)[a-z]|\b(?:personas|empleados|empleadas) de (?!genero|sexo|edad|documento|tipo)[a-z]/.test(pregunta);
if (ubicacion && !consulta.camposNoDisponibles.includes('dirección y ciudad')) consulta.camposNoDisponibles.push('dirección y ciudad');
const trabajo = /\b(cargo|cargos|area|areas|puesto|puestos|profesion|profesiones|trabaja|trabajan|trabajo)\b/.test(pregunta);
if (trabajo && !consulta.camposNoDisponibles.includes('cargo y área de trabajo')) consulta.camposNoDisponibles.push('cargo y área de trabajo');
const documento = pregunta.match(/\b(\d{5,10})\b/);
const stop = new Set('a al anos apellidos area barrio cargo celular ciudad como con cual cuales cuanto cuantos cuanta cuantas de del dime dice documento donde edad el electronico email empleada empleado empleados en es esta estan existe fue fecha genero ha hay hombre hombres identificacion informacion la las los mas mayor mayores me menor menores municipio mujer mujeres nacimiento nacio necesito no nombre numero o por favor persona personas podria podrias profesion puesto que quien quienes registrado registrada registrados registradas registro registrar registrarse registrando se sexo son telefono tiene tienen trabaja trabajan trabajo un una y vive viven correo direccion direcciones ciudades municipios barrios muestra mostrar indica indicar consulta consultar datos verifica verificar encuentra promedio total masculino femenina femenino reciente recientes ultimo ultima ultimos ultimas joven jovenes viejo viejos'.split(' '));
if (consulta.camposNoDisponibles.length || conteo) consulta.objetivo = '';
else if (documento && !/\b(?:edad|ano|anos)\b/.test(pregunta)) consulta.objetivo = documento[1];
else consulta.objetivo = pregunta.replace(/[^a-z0-9]+/g, ' ').trim().split(/\s+/).filter((word) => word && !stop.has(word) && !/^\d+$/.test(word)).join(' ');
return [{ json: consulta }];

const consulta = $('Ajustar consulta').first().json;
const similares = $('Buscar similares').all().map((item) => item.json);
const agregados = $('Agregados').first().json;
const contexto = JSON.stringify({ similares, agregados, filtro_edad: { modo: consulta.ageMode, edad: consulta.ageLimit }, campos_no_disponibles: consulta.camposNoDisponibles }, null, 2);
return [{ json: { pregunta: consulta.pregunta, contexto } }];
